import { useEffect, useState } from 'react'
import { Panel } from './States'

type BackupStatus = {
  sampled_at: string
  manual_backup_available: boolean
  automatic_backups: boolean
  latest_verified_backup: { id: string; tables: number; verified: boolean } | null
}

/** Public deployment metadata, generated by the local launcher from real backups. */
export function LocalBackupStatus(): JSX.Element {
  const [status, setStatus] = useState<BackupStatus | null>(null)
  const [error, setError] = useState<string | null>(null)
  useEffect(() => {
    const controller = new AbortController()
    fetch('/local-status.json', { signal: controller.signal, cache: 'no-store' })
      .then(async (response) => {
        if (!response.ok) throw new Error('本部署尚未提供备份状态')
        const value = await response.json() as BackupStatus
        if (typeof value.sampled_at !== 'string' || typeof value.manual_backup_available !== 'boolean' ||
            typeof value.automatic_backups !== 'boolean' ||
            (value.latest_verified_backup !== null &&
             (typeof value.latest_verified_backup?.id !== 'string' || typeof value.latest_verified_backup?.tables !== 'number' || value.latest_verified_backup?.verified !== true)))
          throw new Error('本部署的备份状态格式无效')
        setStatus(value)
      }).catch((reason: unknown) => {
        if (!controller.signal.aborted) setError(reason instanceof Error ? reason.message : '备份状态读取失败')
      })
    return () => controller.abort()
  }, [])
  return <Panel title="本机备份">
    {error ? <p role="status">{error}；不推断备份是否存在。</p> : null}
    {!status && !error ? <p>正在读取本机备份状态…</p> : null}
    {status ? <>
      <p>手动一致备份：{status.manual_backup_available ? '命令可用' : '未提供'}；自动备份：{status.automatic_backups ? '已配置' : '未配置'}。</p>
      <p>截至服务启动时（{status.sampled_at}）：{status.latest_verified_backup
        ? `最新已核验备份 ${status.latest_verified_backup.id}，${status.latest_verified_backup.tables} 张表，数据库摘要一致。`
        : '没有可核验的备份记录。'}</p>
      <p>执行手动备份：</p><pre>python3 "$HOME/Library/Application Support/JasmineCoreV1/local-item6/bin/manage.py" backup</pre>
      <p>备份时点后的写入不在该备份内。恢复配置与恢复历史数据不同；恢复数据前必须停服务并另存当前库。</p>
    </> : null}
    <p>Storage 容量统计、Devices 管理与在线心跳尚未实现。</p>
  </Panel>
}
